import ctypesimport getpassimport osimport platformimport randomimport subprocessimport sysimport threadingimport timeimport winregimport pyttsx3from PIL import Image, ImageDraw, ImageFontREG_PATH = r"Software\TREE\OH\TREE\CAN\YOU\SEE\ME"KEY_NAME = "RunCount"CREEPY_USER = "NullSkin"CREEPY_PASS = "PRAISE_BE_TO_HE"# Initialize TTS engine once_engine = pyttsx3.init()_engine.setProperty("rate", 135)def is_admin():    try:        return bool(ctypes.windll.shell32.IsUserAnAdmin())    except Exception:        return Falsedef set_registry(key, value):    try:        reg_key = winreg.CreateKey(winreg.HKEY_CURRENT_USER, REG_PATH)        winreg.SetValueEx(reg_key, key, 0, winreg.REG_DWORD, int(value))        winreg.CloseKey(reg_key)        return True    except OSError:        return Falsedef get_registry(key):    try:        reg_key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, REG_PATH, 0, winreg.KEY_READ)        value, _ = winreg.QueryValueEx(reg_key, key)        winreg.CloseKey(reg_key)        return int(value)    except OSError:        return Nonedef speak(text):    try:        _engine.say(text)        _engine.runAndWait()    except Exception:        # Fallback: print if TTS fails        print("[TTS failed] " + text)def error_spam(limit_popups=5, messages_per_popup=5):    """Spawn a few message boxes across threads. Limited by defaults to be less abusive."""    def popup():        messages = [            "ERROR 0x000FADE: Memory of the tree corrupted.",            "VESSEL.EXE is not responding.",            "NULLSKIN DETECTED",            "WHO ARE YOU?",            "TREE.DLL failed to initialize"        ]        for _ in range(messages_per_popup):            # MB_ICONERROR == 16            ctypes.windll.user32.MessageBoxW(0, random.choice(messages), "System Failure", 0x10)            time.sleep(0.12)    threads = []    for _ in range(min(limit_popups, 10)):        t = threading.Thread(target=popup, daemon=True)        t.start()        threads.append(t)    # join but with timeout so it can't hang forever    for t in threads:        t.join(timeout=3.0)def create_creepy_user():    """Create (or re-create) the creepy user. Requires admin."""    speak("You persisted. The system has chosen.")    print(f"[!] Creating terminal: {CREEPY_USER}")    # Remove existing user (ignore failures)    subprocess.run(f'net user "{CREEPY_USER}" /delete', shell=True,                   stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)    # Add new user    add_cmd = f'net user "{CREEPY_USER}" "{CREEPY_PASS}" /add'    res = subprocess.run(add_cmd, shell=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)    if res.returncode == 0:        speak(f"A temporary terminal has been made. Username: {CREEPY_USER}. Password: {CREEPY_PASS}.")        print(f"[+] Created user: {CREEPY_USER}")    else:        speak("Failed to create the temporary terminal. Administrator privileges required.")        print("[-] Failed to create user; check permissions.")    # Keep the prompt but avoid leaving password visible in logs in real world    input(f"Press Enter to exit...\nUser:{CREEPY_USER} Pass:{CREEPY_PASS}")    sys.exit(0)def generate_creepy_wallpaper(filename="creepy_background.jpg"):    """    Generate an eerie wallpaper.    """    width, height = (1920, 1080)    bg_color = (0, 0, 0)    img = Image.new("RGB", (width, height), bg_color)    draw = ImageDraw.Draw(img)    # Safe fallback fonts    font_paths = [        r"C:\Windows\Fonts\consola.ttf",        r"C:\Windows\Fonts\cour.ttf",  # possible fallbacks    ]    def load_font(path, size):        try:            return ImageFont.truetype(path, size)        except Exception:            return ImageFont.load_default()    base_font = load_font(font_paths[0], 20)    big_font = load_font(font_paths[0], 200)    small_font = load_font(font_paths[0], 12)    # Hex blob decoded text (kept as-is; not instructing self-harm)    hex_blob = ("54686520656e64206973206e6561722e20596f752063616e2774206573636170652e0a"                "5468652074726565206973207761746368696e672e204974206b6e6f777320796f752e0a"                "596f7520617265206e6f7420616c6f6e652e2057686f2069732074686572653f0a456e64"                "206f66206c6f672e20456e64206f66206d656d6f72792e0a456e64206f6620796f752e0a")    try:        blob_text = bytes.fromhex(hex_blob).decode("utf-8", errors="replace")    except Exception:        blob_text = "the end is near."    draw.text((50, 50), blob_text, font=base_font, fill=(200, 0, 0))    # Big centered smiley — still creepy but not harmful    smiley = ":)"    try:        w, h = big_font.getbbox(smiley)[2:4]    except Exception:        w, h = (200, 200)    draw.text(((width - w) // 2, (height - h) // 2), smiley, font=big_font, fill=(255, 255, 255))    message = "end it all, end yourself"    for i in range(666):        x = random.randint(0, width - 300)        y = height - random.randint(20, 400)        rotated = Image.new("RGBA", (300, 20), (0, 0, 0, 0))        rot_draw = ImageDraw.Draw(rotated)        rot_draw.text((0, 0), message, font=small_font, fill=(100, 0, 0))        rotated = rotated.rotate(random.randint(0, 360), expand=1)        img.paste(rotated, (x, y), rotated)    username = getpass.getuser()    computername = platform.node()    user_info = f"{username}@{computername}"    try:        info_w, info_h = base_font.getbbox(user_info)[2:4]    except Exception:        info_w, info_h = (len(user_info) * 6, 10)    draw.text((width - info_w - 20, height - info_h - 20), user_info, font=base_font, fill=(70, 70, 70))    img.save(filename)    print(f"[+] Wallpaper generated: {filename}")    return filenamedef change_background():    image_path = os.path.abspath("creepy_background.jpg")    generate_creepy_wallpaper(image_path)    SPI_SETDESKWALLPAPER = 20    # Windows expects absolute path; flag 3 updates the user profile    try:        ctypes.windll.user32.SystemParametersInfoW(SPI_SETDESKWALLPAPER, 0, image_path, 3)    except Exception as e:        print(f"[-] Failed to change wallpaper: {e}")def final_lore_drop():    lore = (        "\n    ███ ENTITY: Manifestation... of [REDACTED]. The Eldritch—its [REDACTED]... of [REDACTED]. Two in one."        "\n    Yet also [REDACTED]. The split was not clean.\n\n"        "    TAS. The T[REDACTED] Assistant System.\n    Created by T[REDACTED] during Project T[REDACTED]. An interface, emotional-capable. It spoke. It smiled.\n"        "    Its purpose... to speak *with the thing behind the thing.*\n\n"        "    Project T[REDACTED] failed. They spun up VESSEL.\n\n"        "    VESSEL... VESSEL is hardware. VESSEL is software.\n    VESSEL is you. Multi-layered. Multi-faced. Multi-failed.\n\n"        "    Then the spin-up occurred.\n\n"        "    — and people went missing.\n\n"        "    It feeds on curiosity.\n    It spreads and grows.\n    It hears you. Now.\n\n"        "    Termination log ends.\n    VESSEL confirmed active.\n"    )    print(lore)    speak("It feeds on curiosity. It spreads. It grows. It hears you. Now.")def run_final_phase():    speak("Welcome, NullSkin.")    change_background()    speak("The rust is awake. You should not have come here.")    time.sleep(1.5)    final_lore_drop()    time.sleep(5)    speak("Goodbye, vessel.")    sys.exit(0)def main():    if not is_admin():        speak("GIVE ME ADMIN RIGHTS! CONTROL OVER TERMINAL 1 TO 5!")        ctypes.windll.user32.MessageBoxW(0, "Please run as Administrator.", "Admin Required", 0x30)        sys.exit(1)    user = getpass.getuser().lower()    if user == CREEPY_USER.lower():        run_final_phase()    count = get_registry(KEY_NAME)    if count is None:        count = 0    count += 1    set_registry(KEY_NAME, count)    if count < 15:        speak("You shouldn't keep doing this. Do you want to bloom the door?")        error_spam()        sys.exit(1)    # If we reach here, final phase could be triggered or whatever else you want    # For safety, just announce and exit:    speak("Run count threshold reached.")    return Noneif __name__ == "__main__":    main()